CREATE TABLE users (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, email VARCHAR(150) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL, role VARCHAR(30) NOT NULL, enabled BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE devices (id BIGINT AUTO_INCREMENT PRIMARY KEY, owner_id BIGINT NOT NULL, category VARCHAR(50) NOT NULL, brand VARCHAR(80) NOT NULL, model VARCHAR(100) NOT NULL, serial_number VARCHAR(120), purchase_price DECIMAL(12,2), purchase_date DATE, notes VARCHAR(1000), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_device_owner FOREIGN KEY (owner_id) REFERENCES users(id));
CREATE TABLE repair_requests (id BIGINT AUTO_INCREMENT PRIMARY KEY, device_id BIGINT NOT NULL, customer_id BIGINT NOT NULL, technician_id BIGINT, title VARCHAR(150) NOT NULL, description VARCHAR(2000) NOT NULL, priority VARCHAR(20) NOT NULL, status VARCHAR(30) NOT NULL, estimated_value DECIMAL(12,2), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_request_device FOREIGN KEY (device_id) REFERENCES devices(id), CONSTRAINT fk_request_customer FOREIGN KEY (customer_id) REFERENCES users(id), CONSTRAINT fk_request_technician FOREIGN KEY (technician_id) REFERENCES users(id));
CREATE TABLE diagnoses (id BIGINT AUTO_INCREMENT PRIMARY KEY, repair_request_id BIGINT NOT NULL UNIQUE, technician_id BIGINT NOT NULL, summary VARCHAR(2000) NOT NULL, repairable BOOLEAN NOT NULL, estimated_success_rate DECIMAL(5,2), diagnosed_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_diagnosis_request FOREIGN KEY (repair_request_id) REFERENCES repair_requests(id), CONSTRAINT fk_diagnosis_technician FOREIGN KEY (technician_id) REFERENCES users(id));
CREATE TABLE quotations (id BIGINT AUTO_INCREMENT PRIMARY KEY, repair_request_id BIGINT NOT NULL, labour_cost DECIMAL(12,2) NOT NULL, parts_cost DECIMAL(12,2) NOT NULL, tax DECIMAL(12,2) NOT NULL, valid_until DATE NOT NULL, status VARCHAR(20) NOT NULL, notes VARCHAR(1000), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_quote_request FOREIGN KEY (repair_request_id) REFERENCES repair_requests(id));
CREATE INDEX idx_request_status ON repair_requests(status); CREATE INDEX idx_request_customer ON repair_requests(customer_id); CREATE INDEX idx_device_owner ON devices(owner_id);
